-- Database Schema for Cost Tracking Test Mission
-- Generated by DatabaseArchitectAgent
-- Conforms to ADR-001 and Domain Invariants

CREATE TABLE IF NOT EXISTS costs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(255) NOT NULL,
    amount_cents BIGINT NOT NULL DEFAULT 0,
    currency VARCHAR(3) NOT NULL DEFAULT 'USD',
    status VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Zero-downtime non-locking compound index on status and timestamps
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_costs_status_created
ON costs (status, created_at DESC);
